def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n >= 99:
        return 'D'
    if n == 1:
        return 'D' if history[0][1] == 'D' else 'C'

    recent_len = 12 if n >= 12 else n
    start_recent = n - recent_len

    opp_c = 0
    recent_c = 0
    after_D_total = 0
    after_D_C = 0

    for i in range(n):
        a, b = history[i]
        if b == 'C':
            opp_c += 1
            if i >= start_recent:
                recent_c += 1
        if i + 1 < n and a == 'D':
            after_D_total += 1
            if history[i + 1][1] == 'C':
                after_D_C += 1

    opp_d = n - opp_c
    recent_d = recent_len - recent_c

    overall_rate = opp_c / float(n)
    recent_rate = recent_c / float(recent_len)
    rate_mix = 0.5 * overall_rate + 0.5 * recent_rate

    last_me, last_opp = history[-1]

    my_recent_D = 0
    start6 = n - 6
    if start6 < 0:
        start6 = 0
    for i in range(start6, n):
        if history[i][0] == 'D':
            my_recent_D += 1

    opp_d_run = 0
    for i in range(n - 1, -1, -1):
        if history[i][1] == 'D':
            opp_d_run += 1
        else:
            break

    dd_run = 0
    if last_me == 'D' and last_opp == 'D':
        for i in range(n - 1, -1, -1):
            if history[i][0] == 'D' and history[i][1] == 'D':
                dd_run += 1
            else:
                break

    # A partner that has never defected so far.  Be cooperative early, then
    # exploit cautiously near the end only after it is clear they tolerate D.
    if opp_d == 0:
        if n >= 85:
            if last_me == 'D' and after_D_C == 0:
                return 'C'
            return 'D'
        return 'C'

    forg_ratio = after_D_C / float(after_D_total) if after_D_total else overall_rate

    # If our defections do not reduce their cooperation much relative to their
    # normal cooperation rate, they are likely non-retaliatory/random/exploitable.
    exploitable = False
    if after_D_total >= 4 and forg_ratio >= 0.45:
        if abs(forg_ratio - overall_rate) <= 0.12:
            exploitable = True
    if after_D_total >= 3 and forg_ratio >= 0.70 and overall_rate >= 0.75:
        exploitable = True

    # If the opponent is still mostly defective and only just gave one C,
    # do not reward the bait too readily.
    if last_opp == 'C' and rate_mix < 0.18:
        return 'D'
    if last_opp == 'C' and opp_d >= opp_c + 5 and recent_d >= 5:
        return 'D'

    # Opponent defected after our cooperation.
    if last_opp == 'D' and last_me == 'C':
        if opp_d >= opp_c + 4 or overall_rate < 0.25:
            return 'D'
        if opp_d_run >= 3:
            return 'D'

        # If this looks like delayed retaliation for our own recent D, offer a
        # truce to break an alternating D/C cycle, unless the partner is already
        # shown to be exploitably forgiving.
        if (
            not exploitable
            and my_recent_D > 0
            and rate_mix > 0.45
            and opp_d_run <= 2
        ):
            if rng.random() < 0.88:
                return 'C'

        # Rare automatic forgiveness against a very cooperative partner.
        if rate_mix > 0.72 and recent_c >= recent_len - 1:
            if rng.random() < 0.10:
                return 'C'

        return 'D'

    # Mutual defection: avoid permanent death spirals, but do not forgive
    # obvious defectors or non-retaliating high-punishment loops.
    if last_me == 'D' and last_opp == 'D':
        if opp_d >= opp_c + 4 or overall_rate < 0.28:
            return 'D'

        if not exploitable and dd_run >= 2 and rate_mix > 0.50:
            prob = 0.40 + 0.45 * rate_mix
            if prob > 0.85:
                prob = 0.85
            if rng.random() < prob:
                return 'C'

        if not exploitable and rate_mix > 0.72 and opp_d_run <= 2:
            if rng.random() < 0.65:
                return 'C'

        return 'D'

    # We defected, they cooperated.  Continue only when they appear forgiving
    # and non-punishing; otherwise restore mutual cooperation.
    if last_opp == 'C' and last_me == 'D':
        if opp_d >= opp_c + 3:
            return 'D'

        if exploitable:
            prob = 0.55 + 0.35 * forg_ratio
            if n >= 80:
                prob += 0.08
            if n >= 93:
                prob += 0.10
            if prob > 0.92:
                prob = 0.92
            if rng.random() < prob:
                return 'D'
            return 'C'

        if n >= 96 and recent_c >= recent_len - 1 and forg_ratio >= 0.60:
            if rng.random() < 0.75:
                return 'D'

        return 'C'

    # Remaining stable case: mutual cooperation.  Preserve it unless there is
    # good evidence that exploitation is cheap or the endgame makes it safe.
    if recent_d >= 5 and rate_mix < 0.55:
        if rng.random() < 0.45:
            return 'D'

    if exploitable and recent_c >= recent_len - 2:
        prob = 0.18 + 0.48 * forg_ratio
        if n >= 70:
            prob += 0.14
        if n >= 88:
            prob += 0.18
        if n >= 96:
            prob = 0.78
        if prob > 0.82:
            prob = 0.82
        if rng.random() < prob:
            return 'D'

    # Very late game: if they have been consistently cooperative and there is
    # no evidence that they punish our D, take the final-round advantage early.
    if n >= 98 and recent_c >= recent_len - 1 and forg_ratio >= 0.60:
        return 'D'

    return 'C'
